"""Convert the rotation capture's node-1/node-3 lookupBlock and shards replies to the ids layout."""

import datetime
import json
import sys

d = json.load(open(sys.argv[1]))
out = {}
for node in ("node-1", "node-3"):
    v = d["nodes"][node]
    out[node] = {}
    for seq, rec in v["lookup"].items():
        out[node][seq] = dict(
            lookup=rec["response"],
            shards=v["shards"][seq]["response"],
            utc=datetime.datetime.fromtimestamp(rec["t"], datetime.UTC).strftime("%Y-%m-%dT%H:%M:%SZ"),
        )
json.dump(out, open(sys.argv[2], "w"), sort_keys=True)

