pack.py.text:
"""Multi-root BOC writer for original cells (deduplicated by representation hash)."""

import lib  # noqa: F401  (sets the vendored codec path)
from pytosiq_core.crypto.crc import crc32c


def write_multi(roots):
    # Deduplicate by representation hash and order parents before children.
    order = []
    state = {}
    canon = {}

    def visit(c):
        h = c._hash
        if h in state:
            if state[h] == 1:
                raise ValueError("cycle")
            return
        state[h] = 1
        canon[h] = c
        for r in c.refs:
            visit(r)
        state[h] = 2
        order.append(h)

    for r in roots:
        visit(r)
    order.reverse()
    index = {h: i for i, h in enumerate(order)}
    n = len(order)
    size = max(1, (n.bit_length() + 7) // 8)
    payload = bytearray()
    for h in order:
        c = canon[h]
        payload += c._descriptors + c._data_bytes
        for r in c.refs:
            j = index[r._hash]
            assert j > index[h]
            payload += j.to_bytes(size, "big")
    off = max(1, (len(payload).bit_length() + 7) // 8)
    flags = 0x40 | size  # crc32c, no index
    out = bytearray(b"\xb5\xee\x9c\x72")
    out += bytes([flags, off])
    out += n.to_bytes(size, "big") + len(roots).to_bytes(size, "big") + (0).to_bytes(size, "big")
    out += len(payload).to_bytes(off, "big")
    for r in roots:
        out += index[r._hash].to_bytes(size, "big")
    out += payload
    out += crc32c(bytes(out))
    return bytes(out)

