"""Write the replay selection: (case, workchain, seqno), with exact masterchain contexts."""

import collections
import json

import lib


def block(wc, seq):
    d, _ = lib.get("block", wc, seq)
    return lib.Block.deserialize(lib.Cell.one_from_boc(d).begin_parse())


def top_shard(seq):
    return block(-1, seq).extra.custom.shard_hashes[0].list[0].seq_no


cases, seen = [], set()


def add(case, wc, seq):
    if (wc, seq) not in seen:
        seen.add((wc, seq))
        cases.append((case, wc, seq))


def with_shards(case, lo, hi):
    """Masterchain lo..hi and every basechain block they register (only the newest one per
    masterchain block can have a two-validator id from a shards reply)."""
    prev_top = top_shard(lo - 1)
    for seq in range(lo, hi + 1):
        add(case, -1, seq)
        top = top_shard(seq)
        for shard_seq in range(prev_top + 1, top + 1):
            add(case, 0, shard_seq)
        prev_top = top


# Token and NFT lifecycle, with every masterchain block of the run.
with_shards("tok01", 117753, 117895)
# ConfigParam 15 critical vote: proposal registration, wallet message, round 1, round 2, rotation
# key block before round 3, round 3, adoption key block.
for seq in (151331, 151410, 151706, 151780, 151828, 151876, 160950, 160997, 161046, 161094, 194882,
            194883, 194884, 195411, 195426, 195440, 195453, 195454, 195455):
    add("cp15", -1, seq)
# Basechain service traffic during round 1, with contract-defined nonzero exit codes.
for seq in (152032, 152121, 152207, 152292, 152381, 152470, 152559):
    add("shard-exits", 0, seq)
# First two-hour validator rotation (key block 230378).
with_shards("rotation", 230373, 230384)
# Exact masterchain contexts of the basechain blocks that a masterchain block registers as newest.
registered = {top_shard(seq) for _, wc, seq in cases if wc == -1}
registered |= {top_shard(seq) for seq in range(151300, 151900)}
for case, wc, seq in list(cases):
    if wc == 0 and seq in registered:
        add("context", -1, block(0, seq).info.master_ref.master.seqno)

cases.sort(key=lambda c: (c[1] != -1, c[2]))
json.dump(cases, open(lib.WORK / "plan.json", "w"))
json.dump([f"{wc}:{seq}" for _, wc, seq in cases], open(lib.WORK / "plan-blocks.json", "w"))
print(len(cases), dict(collections.Counter(c[0] for c in cases)))

resolve.py.text:
"""Find original archive cells for every pruned cell the replay reads.

The diagnostic replay (epoch-replay.cpp plus diagnostic.patch) names each pruned cell it reads and
continues with the next block. Each named hash is looked up in the cell index; the preferred source is
a part already selected, then a block with a two-validator id, then the nearest block. The selected
parts are exactly what assemble.py packs, so the final unmodified replay sees the same cells.
"""

import json
import os
import re
import struct
import subprocess
import sys
from pathlib import Path

import lib
import pack

W = lib.WORK
ZS = Path(os.environ["GENESIS_ZEROSTATE"])
REPLAY = os.environ["REPLAY_DIAG"].split()


def walk(c, seen, out):
    if id(c) in seen:
        return
    seen.add(id(c))
    if not c.is_exotic:
        out.add(c.get_hash(0)[:16])
    for r in c.refs:
        walk(r, seen, out)


def load_index():
    idx = {}
    zero = set()
    for r in lib.Cell.from_boc(ZS.read_bytes()):
        walk(r, set(), zero)
    for h in zero:
        idx[h] = [("zs", 0, 0)]
    for wc in (-1, 0):
        for p in sorted((W / f"idx{wc}").glob("*.bin")):
            b = p.read_bytes()
            o = 0
            while o < len(b):
                seq, part, n = struct.unpack_from("<IBI", b, o)
                o += 9
                for i in range(n):
                    h = b[o + 32 * i : o + 32 * i + 16]
                    v = idx.setdefault(h, [])
                    if len(v) < 64:
                        v.append((wc, seq, part))
                o += 32 * n
    return idx


def main():
    blocks = json.loads(Path(sys.argv[1]).read_text())
    verified = {tuple(x) for x in json.loads(Path(sys.argv[2]).read_text())}
    state = Path(sys.argv[3])
    sources = {}
    idx = load_index()
    print("index", len(idx), flush=True)
    bdir = W / "resolve"
    bdir.mkdir(exist_ok=True)

    def block_path(wc, seq):
        p = bdir / f"{wc}-{seq}.boc"
        p.write_bytes(lib.get("block", wc, seq)[0])
        return str(p)

    def part_path(key):
        if key == "zs":
            return str(ZS)
        wc, seq = map(int, key.split(":"))
        parts = sorted(set(sources[key]["parts"]))
        root = lib.Cell.one_from_boc(lib.get("block", wc, seq)[0])
        cells = [root.refs[2]] + ([root.refs[3]] if 2 in parts else [])
        p = bdir / f"part-{wc}-{seq}-{''.join(map(str, parts))}.boc"
        p.write_bytes(pack.write_multi(cells))
        return str(p)

    (W / "resolve.blocks").write_text("".join(block_path(*map(int, b.split(":"))) + "\n" for b in blocks))
    for it in range(1000):
        (W / "resolve.sup").write_text("".join(part_path(s) + "\n" for s in sorted(sources)))
        r = subprocess.run(REPLAY + ["--run", str(W / "resolve.blocks"), str(W / "resolve.sup")],
                           capture_output=True, text=True)
        cur, misses, fails = None, [], 0
        for line in r.stderr.splitlines():
            m = re.match(r"replay (\S+)", line)
            if m:
                cur = m.group(1)
            m = re.match(r"pruned cell ([0-9A-F]{64}) while reading (.*)", line)
            if m:
                misses.append((m.group(1), m.group(2), cur))
            m = re.match(r"DIAGFAIL (\S+) (.*)", line)
            if m:
                fails += 1
                if "prunned branch" not in m.group(2):
                    raise SystemExit(f"replay failure that is not a missing cell: {line}")
        print(f"iteration {it}: sources {len(sources)} failing blocks {fails} missing cells {len(misses)}",
              flush=True)
        if not fails:
            break
        added = 0
        for h, what, target in misses:
            found = idx.get(bytes.fromhex(h)[:16])
            if not found:
                raise SystemExit(f"no original preimage of {h} ({what}, {target})")
            twc, tseq = map(int, Path(target).stem.rsplit("-", 1))

            def score(o):
                key = "zs" if o[0] == "zs" else f"{o[0]}:{o[1]}"
                have = key in sources and (o[2] != 2 or 2 in sources[key]["parts"])
                if o[0] == "zs":
                    return (0 if have else 1, 2, 1, 0)
                return (0 if have else 1, 0 if (o[0], o[1]) in verified else 1, 0 if o[0] == twc else 1,
                        abs(o[1] - tseq))

            best = min(found, key=score)
            key = "zs" if best[0] == "zs" else f"{best[0]}:{best[1]}"
            if key not in sources:
                sources[key] = dict(parts=[best[2]], cell=h, first_needed_by=Path(target).name, stage=what)
                added += 1
            elif best[2] == 2 and 2 not in sources[key]["parts"]:
                sources[key]["parts"].append(2)
                added += 1
        state.write_text(json.dumps(sources, indent=1, sort_keys=True) + "\n")
        if not added:
            raise SystemExit("no progress")
    state.write_text(json.dumps(sources, indent=1, sort_keys=True) + "\n")
    print("resolved", len(sources), "sources;", len(r.stdout.splitlines()), "records")


main()

