"""Require node-1 and node-3 to give one identical full id per block, equal to the archive bytes."""

import hashlib
import json
import sys

import lib

ids = {}


def add(wc, seq, node, rid):
    v = (lib.b64hex(rid["root_hash"]), lib.b64hex(rid["file_hash"]), int(rid["shard"]))
    ids.setdefault((wc, seq), {}).setdefault(node, set()).add(v)


for path in sys.argv[1:]:
    for node, per in json.load(open(path)).items():
        for seq, rec in per.items():
            look = rec["lookup"]["result"]
            assert int(look["seqno"]) == int(seq) and look["workchain"] == -1
            add(-1, int(seq), node, look)
            for s in rec["shards"]["result"]["shards"]:
                add(s["workchain"], int(s["seqno"]), node, s)
bad, ok, missing = [], [], 0
for (wc, seq), nodes in sorted(ids.items()):
    if set(nodes) != {"node-1", "node-3"} or any(len(v) != 1 for v in nodes.values()) or len(
        {next(iter(v)) for v in nodes.values()}
    ) != 1:
        bad.append((wc, seq, "validators disagree or one is missing"))
        continue
    root, fh, shard = next(iter(nodes["node-1"]))
    data, _ = lib.get("block", wc, seq)
    if data is None:
        missing += 1
        continue
    if (
        lib.Cell.one_from_boc(data).hash.hex().upper() != root
        or hashlib.sha256(data).hexdigest().upper() != fh
        or shard != -(2**63)
    ):
        bad.append((wc, seq, "archive bytes differ from the full id"))
        continue
    ok.append((wc, seq))
print("ids", len(ids), "ok", len(ok), "missing-in-archive", missing, "bad", len(bad))
for b in bad:
    print(b)
json.dump(ok, open(lib.WORK / "verified.json", "w"))
sys.exit(1 if bad else 0)
